if (typeof msg.payload === 'string') {
    try {
        msg.payload = JSON.parse(msg.payload);
    } catch(e) {
        node.error('JSON format error: ' + msg.payload);
        return null;
    }
}
node.warn(msg.payload);

let uid = msg.payload.user_id;
if (uid === 'U001') {
    return [msg, msg, null];
} else if (uid === 'U002') {
    return [msg, null, msg];
} else {
    return [null, null, null];
}

