const LINE_USER_ID = env.get("LINE_FAMILY2_USER_ID") || "";
const LINE_TOKEN = env.get("LINE_CHANNEL_ACCESS_TOKEN") || "";

msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + LINE_TOKEN
};

var data = msg.payload;

msg.payload = {
    to: LINE_USER_ID,
    messages: [
        {
            type: 'text',
            text: `⚠️ ALERT: FALL DETECTED\n👤 Name: ${data.name}\n📍 Loc: ${data.location}\n🕒 Time: ${data.timestamp}\n📷 Device: ${data.device_id}`
