var now = new Date();
msg.payload.server_timestamp = now;
msg.payload.local_time = now.toLocaleString("zh-TW", {
    timeZone: "Asia/Taipei",
    hour12: false
});
return msg;

var startStr = "2025-12-25T08:00:00+08:00";
var endStr   = "2025-12-25T22:00:00+08:00";
var currentTime = new Date(startStr).getTime();
var endTime = new Date(endStr).getTime();
var anomalyTime = new Date("2025-12-25T16:30:00+08:00").getTime();

var dataBatch = [];
var currentState = "Sitting";
var nextGapTime = currentTime + rnd(30, 60) * 60 * 1000;

function rnd(min, max) { return Math.random() * (max - min) + min; }

while (currentTime <= endTime) {
    if (currentTime >= nextGapTime) {
        var gapDuration = rnd(5, 15) * 60 * 1000;
        currentTime += gapDuration;
        nextGapTime = currentTime + rnd(45, 90) * 60 * 1000;
        continue;
    }

    if (Math.random() < 0.01) {
        currentState = (currentState === "Sitting") ? "Walking" : "Sitting";
    }

    var gait = 0, balance = 0, activity = 0;
    var stateLabel = currentState;

    if (currentTime >= anomalyTime && currentTime < (anomalyTime + 10000)) {
        gait = rnd(55, 60);
        balance = rnd(0.5, 0.6);
        activity = rnd(80, 120);
        stateLabel = "Unstable";
    } else {
        if (currentState === "Sitting") {
            gait = rnd(95, 100);
            balance = rnd(0.95, 1.0);
            activity = rnd(5, 20);
        } else {
            gait = rnd(85, 98);
            balance = rnd(0.8, 0.95);
            activity = rnd(50, 150);
        }
    }

    var tsObj = new Date(currentTime);
    var localStr = tsObj.toLocaleString("zh-TW", {timeZone: "Asia/Taipei", hour12: false});

    dataBatch.push({
        user_id: "U002",
        gait_score: parseFloat(gait.toFixed(1)),
        balance: parseFloat(balance.toFixed(2)),
        activity: parseFloat(activity.toFixed(1)),
        sway: parseFloat(rnd(2, 10).toFixed(1)),
        state: stateLabel,
        location: "Living Room",
        server_timestamp: tsObj,
        local_time: localStr
    });

    currentTime += 1000;
}

msg.payload = dataBatch;
return msg;

var event = msg.payload.events[0];
if (!event || !event.replyToken) return null;
msg.replyToken = event.replyToken;

if (event.type === 'postback') {
    if (event.postback.params && event.postback.params.date) {
        msg.queryDate = event.postback.params.date;
        return [msg, null, null];
    }
    if (event.postback.data && event.postback.data.indexOf("date=") === 0) {
        msg.queryDate = event.postback.data.split('=')[1];
        return [msg, null, null];
    }
}

if (event.type === 'message' && event.message.type === 'text') {
    var text = event.message.text.trim().toLowerCase();
    if (text === "menu" || text === "查詢" || text === "help") {
        return [null, null, msg];
    }
    var dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (dateRegex.test(event.message.text.trim())) {
        msg.queryDate = event.message.text.trim();
        return [msg, null, null];
    }
    msg.payload = "Please type 'Menu' to select a date.";
    return [null, msg, null];
}
return null;

var dateStr = msg.queryDate;
var startISO = dateStr + "T00:00:00.000+08:00";
var endISO   = dateStr + "T23:59:59.999+08:00";

msg.payload = {
    "server_timestamp": {
        "$gte": new Date(startISO),
        "$lte": new Date(endISO)
    }
};
return msg;

var data = msg.payload;
if (!data || data.length === 0) {
    msg.payload = "No records found for " + msg.queryDate;
    return [null, msg, null];
}

var buckets = {};
var labels = [], gait = [], bal = [], act = [];

data.forEach(function(item) {
    var d = new Date(item.server_timestamp);
    var m = Math.floor(d.getMinutes() / 5) * 5;
    var key = d.getHours() + ":" + ("0" + m).slice(-2);
    if (!buckets[key]) buckets[key] = {c:0, g:0, b:0, a:0};
    buckets[key].c++;
    buckets[key].g += item.gait_score;
    buckets[key].b += item.balance;
    buckets[key].a += item.activity;
});

Object.keys(buckets).sort(function(a,b){
    return parseInt(a.replace(':','')) - parseInt(b.replace(':',''));
}).forEach(function(key){
    var b = buckets[key];
    labels.push(key);
    gait.push((b.g/b.c).toFixed(1));
    bal.push(((b.b/b.c)*100).toFixed(1));
    act.push((b.a/b.c).toFixed(1));
});

msg.payload = {
    chart: {
        type: 'line',
        data: {
            labels: labels,
            datasets: [
                { label: 'Gait', data: gait, borderColor: 'green', fill: false, yAxisID:'y1', pointRadius:0, lineTension:0.4 },
                { label: 'Balance', data: bal, borderColor: 'red', fill: false, borderDash:[5,5], yAxisID:'y1', pointRadius:0, lineTension:0.4 },
                { label: 'Activity', data: act, borderColor: 'blue', fill: true, backgroundColor:'rgba(0,0,255,0.1)', yAxisID:'y2', pointRadius:0, lineTension:0.4 }
            ]
        },
        options: {
            title: { display: true, text: msg.queryDate + ' Gait Report', fontSize: 18 },
            legend: { position: 'bottom' },
            scales: {
                yAxes: [
                    { id: 'y1', position:'left', ticks:{min:0, max:100} },
                    { id: 'y2', position:'right', gridLines:{display:false} }
                ]
            }
        }
    },
    width: 800,
    height: 500,
    format: 'png',
    backgroundColor: 'white'
};
return [msg, null, null];

